contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // amount: Ether to send to c.play (must be provided by caller)
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // Observables before the call
        address beforeBank = c.bank(); if (__ESBMC_reverted()) return;
        uint beforePot = c.pot(); if (__ESBMC_reverted()) return;
        uint beforeBalanceC = address(c).balance;

        bool reverted;
        // perform the call
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observables after the call
        address afterBank = c.bank(); if (__ESBMC_reverted()) return;
        uint afterPot = c.pot(); if (__ESBMC_reverted()) return;
        uint afterBalanceC = address(c).balance;

        // General rule:
        // - bank never changes
        // - if reverted: pot and contract balance unchanged
        // - if not reverted: either pot increased by exactly amount (ticket paid in)
        //   or pot became 0 (payout case). We don't assume knowledge of internal constants
        //   so express increase as afterPot == beforePot + amount.
        assert(
            afterBank == beforeBank
            && (
                reverted
                ? (afterPot == beforePot && afterBalanceC == beforeBalanceC)
                : (
                    (amount > 0 && afterPot == beforePot + amount && afterBalanceC == beforeBalanceC + amount)
                    || (afterPot == 0)
                )
            )
        );
    }

    receive() external payable {}
}

