// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        address beforeBank;
        try c.bank() returns (address __r) { beforeBank = __r; } catch { return; }
        uint256 beforePot;
        try c.pot() returns (uint256 __r) { beforePot = __r; } catch { return; }
        uint beforeBalanceC = address(c).balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address afterBank;
        try c.bank() returns (address __r) { afterBank = __r; } catch { return; }
        uint256 afterPot;
        try c.pot() returns (uint256 __r) { afterPot = __r; } catch { return; }
        uint afterBalanceC = address(c).balance;
        assertTrue(afterBank == beforeBank
            && (
                reverted
                ? (afterPot == beforePot && afterBalanceC == beforeBalanceC)
                : (
                    (amount > 0 && afterPot == beforePot + amount && afterBalanceC == beforeBalanceC + amount)
                    || (afterPot == 0)
                )
            ));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
